let tab='video',selected=null,pending=null,playing=false,seconds=0,queue=[],slideTimer=null;const media=[{id:'demo-video-1',name:'A quiet horizon',kind:'video',duration:360,cover:'horizon.svg',resume:72},{id:'demo-video-2',name:'City of light',kind:'video',duration:240,cover:'city.svg',resume:0},{id:'demo-audio-1',name:'Blue hour',kind:'audio',duration:180,cover:'music.svg'},{id:'demo-audio-2',name:'Slow orbit',kind:'audio',duration:210,cover:'music.svg'},{id:'demo-photo-1',name:'Mountain morning',kind:'photo',duration:0,cover:'horizon.svg'},{id:'demo-photo-2',name:'Evening geometry',kind:'photo',duration:0,cover:'city.svg'}];let library=window.omnibloomHost?[]:media,live=!!window.omnibloomHost;const fmt=n=>Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');function draw(){const box=$('#library');box.innerHTML=library.filter(x=>x.kind===tab).map(x=>'<article class="card"><img class="cover" src="'+esc(x.cover)+'" alt="Original abstract cover"><h2>'+esc(x.name)+'</h2><p>'+esc(x.kind==='photo'?'Photo':fmt(x.duration))+'</p><div class="actions"><button data-open="'+esc(x.id)+'" class="primary">'+(x.kind==='photo'?'View':'Play')+'</button>'+(x.kind==='audio'?'<button data-add="'+esc(x.id)+'">Add to queue</button>':'')+'</div></article>').join('');$$('[data-open]').forEach(b=>b.onclick=()=>openMedia(b.dataset.open));$$('[data-add]').forEach(b=>b.onclick=()=>{queue.push(b.dataset.add);drawQueue();notice('Added to queue.')})}function drawQueue(){$('#queue').textContent=queue.length?'Queue: '+queue.map(id=>library.find(x=>x.id===id)?.name||id).join(' → '):'Queue is empty.'}function stopSlides(){clearInterval(slideTimer);slideTimer=null;$('#slides').textContent='Start slideshow'}function syncControls(){const m=MediaControls.mode(tab);for(const [key,id]of Object.entries({timeline:'timeline-controls',subtitles:'subtitle-controls',transport:'transport-controls',queue:'queue-controls',photo:'photo-controls'}))$('#'+id).hidden=!m[key];const photo=selected?.kind==='photo'?selected:null;$('#photo-preview').hidden=!photo;if(photo){$('#photo-preview').src=photo.cover;$('#photo-preview').alt=photo.name}$('#photo-info').textContent=photo?photo.name+' · '+(live?'Files thumbnail preview':'Original demo image'):'Choose a photo to view.';$('#slides').disabled=!library.some(x=>x.kind==='photo')}function tick(){syncControls();$('#now').textContent=selected?selected.name:tab==='photo'?'Choose a photo':'Choose something to play';$('#playstate').textContent=selected?.kind==='photo'?'Photo':tab==='photo'?'Photo library':playing?'Playing · '+(live?'native':'demo clock'):'Paused';$('#position').textContent=fmt(seconds)+' / '+fmt(selected?.duration||0);$('#progress').max=selected?.duration||100;$('#progress').value=seconds;$('#caption').textContent=selected?.kind==='video'&&$('#subtitles').value==='en'?'[Demo caption] A little space to explore.':''}function resumeValue(m){if(live)return m.resume||0;try{return Number(localStorage.getItem('ob.demo.resume.'+m.id))||m.resume||0}catch(e){return m.resume||0}}async function begin(m,start){try{if(live&&m.kind!=='photo'){const opened=await request('files.open',{fileHandle:m.id,mode:'read',purpose:'media-playback'});if(typeof opened.playbackToken!=='string')throw new Error('The Files helper did not return a playback token.');await request('media.play',{fileId:m.id,playbackToken:opened.playbackToken,positionSeconds:start,subtitles:$('#subtitles').value,renderer:'hardware'});}selected=m;seconds=start;playing=m.kind!=='photo';tick();notice(m.kind==='photo'?(live?'Files thumbnail preview; full-resolution photo bridge is pending.':'Original demo photo preview.'):(live?'Playback request accepted.':'Demo playback state only; no media decoding occurs.'))}catch(e){failure(e)}}function openMedia(id){const m=library.find(x=>x.id===id);if(!m)return;const resume=resumeValue(m);if(m.kind==='video'&&resume>0&&resume<m.duration-10){pending=m;$('#resume-info').textContent=m.name+' · '+fmt(resume);openDialog('#resume')}else begin(m,0)}$('#resume-yes').onclick=()=>{const m=pending;closeDialog();begin(m,resumeValue(m))};$('#resume-no').onclick=()=>{const m=pending;closeDialog();begin(m,0)};$$('[data-tab]').forEach(b=>b.onclick=async()=>{const nextTab=b.dataset.tab;if(nextTab===tab)return;try{if(live&&selected&&selected.kind!=='photo')await request('media.stop',{fileId:selected.id});stopSlides();playing=false;selected=null;seconds=0;pending=null;tab=nextTab;$$('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',x===b));draw();tick();notice('Choose '+(tab==='photo'?'a photo.':tab==='audio'?'a track.':'a video.'))}catch(e){failure(e)}});$('#choose').onclick=async()=>{if(!window.omnibloomHost){notice('Demo USB selected. Native Files bridge is not connected.');return}try{const r=await request('files.pick',{kind:'directory',scope:'usb',purpose:'media-library'});const result=await request('media.list',{directoryHandle:r.handle,cursor:null,limit:60});if(!Array.isArray(result.items)||result.items.length>60||result.items.some(x=>!x||typeof x.id!=='string'||x.id.length>160||typeof x.name!=='string'||x.name.length>160||!['video','audio','photo'].includes(x.kind)||!Number.isFinite(x.duration)||x.duration<0||x.duration>86400||typeof x.cover!=='string'||x.cover.length>200000||!(/^(horizon|city|music)\.svg$/.test(x.cover)||/^data:image\/(webp|png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(x.cover))))throw new Error('The Files helper returned an invalid library.');library=result.items;live=true;$('#drive').textContent=result.label||'USB drive';draw()}catch(e){failure(e)}};$('#play').onclick=async()=>{if(!selected||selected.kind==='photo'||tab==='photo')return notice('Choose a video or track first.');try{if(live)await request(playing?'media.pause':'media.resume',{fileId:selected.id});playing=!playing;tick()}catch(e){failure(e)}};$('#seek').onclick=async()=>{if(!selected||selected.kind==='photo')return notice('Choose a video or track first.');const next=Math.min(selected.duration,seconds+30);try{if(live)await request('media.seek',{fileId:selected.id,positionSeconds:next});seconds=next;tick()}catch(e){failure(e)}};$('#stop').onclick=async()=>{try{if(live&&selected)await request('media.stop',{fileId:selected.id});playing=false;clearInterval(slideTimer);slideTimer=null;$('#slides').textContent='Start slideshow';tick()}catch(e){failure(e)}};$('#next').onclick=()=>{if(tab!=='audio'||!queue.length)return notice('Add a track to the queue first.');openMedia(queue.shift());drawQueue()};$('#subtitles').onchange=async()=>{try{if(selected?.kind!=='video'||tab!=='video')return;if(live&&selected)await request('media.subtitles',{fileId:selected.id,trackId:$('#subtitles').value});tick()}catch(e){failure(e)}};$('#slides').onclick=()=>{if(tab!=='photo')return;if(slideTimer){clearInterval(slideTimer);slideTimer=null;$('#slides').textContent='Start slideshow';return}const photos=library.filter(x=>x.kind==='photo');if(!photos.length)return notice('No photos on this drive.');let i=0;function show(){selected=photos[i++%photos.length];playing=false;seconds=0;tick()}show();slideTimer=setInterval(()=>{if(!document.hidden)show()},5000);$('#slides').textContent='Stop slideshow'};setInterval(()=>{if(!document.hidden&&playing&&selected&&!live){seconds=Math.min(selected.duration,seconds+1);if(selected.kind==='video')try{localStorage.setItem('ob.demo.resume.'+selected.id,String(seconds))}catch(e){}if(seconds>=selected.duration){playing=false;if(selected.kind==='audio'&&queue.length){const next=queue.shift();openMedia(next);drawQueue()}}tick()}},1000);window.addEventListener('omnibloom:media',e=>{const s=e.detail;if(live&&selected&&s?.fileId===selected.id&&Number.isFinite(s.positionSeconds)){seconds=s.positionSeconds;playing=s.state==='playing';tick()}});draw();drawQueue();tick();window.addEventListener('omnibloom:files',e=>{if(e.detail?.type==='drive-removed'){playing=false;stopSlides();selected=null;library=[];draw();tick();notice('OB-MEDIA-004 · USB drive removed. Reconnect it, then choose the drive again.')}});
window.addEventListener('pagehide',()=>{stopSlides();playing=false});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSlides()});

if(window.omnibloomHost){document.getElementById('drive').textContent='No drive selected';notice('Choose a drive through Files.');}
